shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
path = Path('test/xchar-test.cc')
text = path.read_text()
anchor = 'TEST(locale_test, format) {\n'
addition = '''TEST(locale_test, localized_double_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<char>());
  EXPECT_EQ("              0?295", fmt::format(loc, "{:19.3Lf}", 0.295));
  EXPECT_EQ("             -0?295", fmt::format(loc, "{:19.3Lf}", -0.295));
  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295));
  EXPECT_EQ("          2~194?139", fmt::format(loc, "{:19.3Lf}", 2194.139));
  EXPECT_EQ("    12?345", fmt::format(loc, "{:10.3Lf}", 12.345));
  EXPECT_EQ("  0?295000", fmt::format(loc, "{:10.6Lf}", 0.295));
  EXPECT_EQ("    1?2345", fmt::format(loc, "{:10L}", 1.2345));
  EXPECT_EQ("0?295*****", fmt::format(loc, "{:*<10.3Lf}", 0.295));
  EXPECT_EQ("**0?295***", fmt::format(loc, "{:*^10.3Lf}", 0.295));
}

TEST(locale_test, localized_wide_double_alignment) {
  auto loc = std::locale(std::locale(), new numpunct<wchar_t>());
  EXPECT_EQ(L"              0?295", fmt::format(loc, L"{:19.3Lf}", 0.295));
  EXPECT_EQ(L"             -0?295", fmt::format(loc, L"{:19.3Lf}", -0.295));
  EXPECT_EQ(L"          2~194?139", fmt::format(loc, L"{:19.3Lf}", 2194.139));
  EXPECT_EQ(L"**0?295***", fmt::format(loc, L"{:*^10.3Lf}", 0.295));
}

'''
assert text.count(anchor) == 1
path.write_text(text.replace(anchor, addition + anchor))
PY
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized*double_alignment'

